// VictorySystem::update (0x001DFBA0): slot 5 of VictorySystem's table
// 0x0109FD8C, the SubsystemInterface update slot (init 1 is
// VictorySystem::init; WeaponStore::update and InGameUI::update sit in slot 5
// of their tables). When active it feeds the selected cell grid the player's
// victory parameters, then applies the winning cells and decays all cells.

typedef int Int;

struct FactionVictoryParameters;

// The grid sweep (0x001B1AD0), under its ledger name.
class BfmeCellGrid
{
public:
	void rva001B1AD0( Int playerIndex, void *parameters );
};

class VictorySystem
{
public:
	virtual void update( void );

	FactionVictoryParameters *bfmeParametersForPlayer( Int playerIndex );
	void bfmeApplyWinningCells( void );
	void bfmeDecayAllCells( void );

private:
	char m_unmodelled004[0xf8 - 0x04];
	BfmeCellGrid *m_grids[2];								///< this+0xF8
	bool m_bfme100;											///< this+0x100, update runs only when set
	char m_unmodelled101[0x3];
	Int m_bfmeGridIndex104;									///< this+0x104, 0 or 1 picks m_grids
	Int m_bfmePlayerIndex108;								///< this+0x108
};

// ?update@VictorySystem@@UAEXXZ
void VictorySystem::update( void )
{
	if( !m_bfme100 )
		return;

	BfmeCellGrid *grid;
	switch( m_bfmeGridIndex104 )
	{
		case 0:
			grid = m_grids[0];
			break;
		case 1:
			grid = m_grids[1];
			break;
		default:
			grid = 0;
			break;
	}

	if( grid )
	{
		Int playerIndex = m_bfmePlayerIndex108;
		grid->rva001B1AD0( playerIndex, bfmeParametersForPlayer( playerIndex ) );
	}

	bfmeApplyWinningCells();
	bfmeDecayAllCells();
}
